<?php
use App\Models\Task; use App\Services\TaskWorkflowService; use Livewire\Attributes\Computed; use Livewire\Attributes\Title; use Livewire\Component;
new #[Title('កិច្ចការរបស់ខ្ញុំ')] class extends Component{
public array $progress=[];public array $notes=[];
public function mount():void{abort_unless(auth()->user()?->employee&&auth()->user()?->can('task.view-own'),403);}
#[Computed]public function tasks(){return Task::query()->where('assigned_to',auth()->user()->employee->id)->where('status','!=','cancelled')->latest('due_date')->get();}
public function submit(int $id,TaskWorkflowService $s):void{$this->validate(["progress.$id"=>['required','integer','min:0','max:100'],"notes.$id"=>['nullable','string','max:1500']]);try{$s->updateProgress(Task::findOrFail($id),auth()->user(),(int)$this->progress[$id],$this->notes[$id]??null);}catch(\DomainException $e){$this->addError("progress.$id",$e->getMessage());return;}unset($this->progress[$id],$this->notes[$id],$this->tasks);session()->flash('success','បានបញ្ជូនវឌ្ឍនភាព។');}};?>
<div class="space-y-6"><div><flux:heading size="xl">កិច្ចការរបស់ខ្ញុំ</flux:heading><flux:subheading>តាមដានវឌ្ឍនភាព និងបញ្ជូនកិច្ចការសម្រាប់ផ្ទៀងផ្ទាត់</flux:subheading></div>@if(session('success'))<div class="rounded-xl border border-green-200 bg-green-50 p-4 text-green-800">{{session('success')}}</div>@endif<div class="grid gap-4 xl:grid-cols-2">@forelse($this->tasks as $task)<article class="space-y-4 rounded-2xl border border-zinc-200 bg-white p-5 dark:border-zinc-700 dark:bg-zinc-900"><div class="flex justify-between gap-3"><div><flux:heading size="lg">{{$task->title}}</flux:heading><div class="text-sm text-zinc-500">កំណត់ {{$task->due_date->format('d/m/Y')}}</div></div><flux:badge>{{$task->effective_status}}</flux:badge></div><p class="text-sm">{{$task->description}}</p><div class="rounded-xl bg-zinc-50 p-4 dark:bg-zinc-800/60">វឌ្ឍនភាពដែលបានទទួលស្គាល់: <strong>{{$task->progress}}%</strong></div>@if(!in_array($task->status,['waiting_verification','verified']))<div class="grid gap-3 sm:grid-cols-2"><flux:input wire:model="progress.{{$task->id}}" type="number" min="0" max="100" label="វឌ្ឍនភាព % *"/><flux:input wire:model="notes.{{$task->id}}" label="កំណត់សម្គាល់"/><div class="sm:col-span-2 flex justify-end"><flux:button variant="primary" wire:click="submit({{$task->id}})">បញ្ជូន</flux:button></div></div>@endif @if($task->manager_note)<div class="text-sm text-zinc-500">មតិអ្នកគ្រប់គ្រង: {{$task->manager_note}}</div>@endif</article>@empty<div class="rounded-2xl border border-dashed p-12 text-center text-zinc-500 xl:col-span-2">មិនទាន់មានកិច្ចការ។</div>@endforelse</div></div>
